P.entries["zone:swampofsorrows"] = {n="Болото Скорботи",s="Болото Скорботи — каламутні солонуваті мочарі між Перевалом Мертвого Вітру й посушливими Спустошеними Землями. Колись це була північна частина давньої Чорної Трясовини, а нині на її вкритих сольовою кіркою драговинах живуть небезпечні звірі й зелені драконороди, а на дні Ставка Сліз лежать руїни затонулого Храму Атал'Гаккара. Орда утримує тут укріплений гарнізон Стонард, а Альянс не має в трясовині безпечного прихистку, тож край лишається здебільшого диким.",h="Болото Скорботи — каламутні солонуваті мочарі між Перевалом Мертвого Вітру й посушливими Спустошеними Землями.",kw={"болото скорботи","стонард","храм атал'гаккара","затонулий храм","ставок сліз","загублені","ераникус"},ang={["faction:Alliance"]="Без застави, де можна перевести дух, подорож болотом — самотня, небезпечна справа, до якої варто ретельно підготуватися в Даркширі чи Замку Незерґард.",["faction:Horde"]="Стонард — ваш важливий передовий оплот на південному континенті, звідки виверни літають просто до Карґата, Полум'яного Гребеня й Базового Базового Табору Ґром'ґол.",["profession:Blacksmithing"]="Загартовані шукачі пригод можуть добувати залізо, золото, мітрил та справжнє срібло на гірських кручах уздовж північного й південного країв болота.",["profession:Herbalism"]="Болото — одне з небагатьох місць Азероту, багатих на Сліпотрав, а ще тут щедро ростуть Живокорінь, Блідолист і Душиводорість.",["race:Troll"]="Затоплені руїни Атал'Гаккара — грізне нагадування про темну магію крові, що розколола Імперію Ґурубаші й накликала гнів Аспектів драконів."},sec={{t="Потоплена історія",b="Задовго до приходу орочої Орди ці мочарі становили північну половину величезних боліт, відомих як Чорна Трясовина. Після розпаду Імперії Ґурубаші фанатичні тролі атал'аї втекли в трясовину й звели Храм Атал'Гаккара, щоб викликати свого кровожерного лоа — Гаккара Душолупа. Відчувши наближення катастрофи, Аспект Ізера вивільнила свою силу й затопила прокляту піраміду у водах Ставка Сліз. Охоронці із зеленого драконячого роду на чолі з Ераникусом залишилися тут пильно стерегти затоплену споруду. Коли ж згодом катаклізм Темного Порталу випалив південну частину трясовини на Спустошені Землі, це північне болото дістало свою нинішню скорботну назву."},{t="Застави й зламані вигнанці",b="Стонард — головний осередок цивілізації на болоті. Цю заставу заснували ще в Першу війну разом із нині зруйнованими поселеннями Рокард і Кірос, а за Тралла її відбудували як найпівденніший плацдарм Орди у Східних Королівствах. За частоколом Стонарда болотом блукають дивні мандрівники. Гурт дренеїв, що застрягли в Азероті, піддався тузі за домом і безумству й виродився в диких Загублених. Проте невелика громада Зламаних, які зберегли ясний розум, живе в Пристанищі: вони насторожені, але готові мирно торгувати з мандрівниками."},{t="Драговина, що засмоктує",b="Щоб вижити на болоті, треба постійно стерегтися його хижих мешканців. Глибокі драговини ховають кроколісків, що кидаються з води, отруйних павуків, болотяних ягуарів і бродячих болотяних звірів, обліплених намулом. Прибережні печери й Узбережжя Туманного Очерету кишать лютими мурлоками, а солона вода невпинно підступає вглиб суходолу, консервуючи гнилі колоди в товстій сольовій кірці. Далі на сході лежить Скорботна Мла, де агресивні елітні драконороди люто стережуть підступи до Затонулого Храму, нападаючи на кожного, хто наблизиться."}},faq={{q="Як дістатися до Болота Скорботи?",a="Найпоширеніший суходільний шлях веде на схід від Даркшира в Сутінколіссі, крізь небезпечну моторошну ущелину Перевалу Мертвого Вітру, і просто вниз, у болото. А мандрівники з півдня можуть пройти на північ головною дорогою зі Спустошених Земель.",al={"як дістатися до болота скорботи","дорога болота скорботи","дістатися до стонарда"}},{q="Чому Храм Атал'Гаккара під водою?",a="Століття тому жрецтво Атал'аї спробувало викликати Гаккара Душолупа в Азерот. Ізера, Аспект зеленої драконячого роду, викрила їхні демонічні криваві обряди й затопила весь храм у болоті, щоб відвернути лихо, лишивши зелених драконородів стерегти затоплені зали.",al={"чому затонулий храм під водою","хто потопив храм","лор затонулого храму"}},{q="Що таке Стонард?",a="Стонард — одне з перших поселень, які Орда збудувала, перейшовши крізь Темний Портал у Першій війні. Спустошений у боях, він нещодавно був відвойований і відбудований за наказом Тралла, щоб стати опорою постачання Орди біля Спустошених Земель.",al={"історія стонарда","орківська база на болоті","хто збудував стонард"}},{q="Чи є тут поселення Альянсу?",a="Ні. У Болоті Скорботи Альянс не має ні містечок, ні варти, ні шляхів польоту. Шукачам пригод з Альянсу, що діють у цьому краї, доводиться базуватися в Даркширі в Сутінколіссі на заході чи в Замку Незерґард у Спустошених Землях на півдні.",al={"база альянсу болото скорботи","політ альянсу болото","де табір альянсу"}},{q="Хто ці дивні спотворені людиноподібні в болоті?",a="Це дренеї, що застрягли в Азероті після руйнування Темного Порталу. Відрізані від свого світу, більшість збожеволіла з відчаю й стала ворожими Загубленими. Невелика громада розважливих вигнанців із Розбитих знайшла прихисток на північному заході, у Пристані, обравши нейтральне виживання замість безумної люті.",al={"хто загублені","що таке притулок","дренеї на болоті"}},{q="Що таке Скорботна Мла?",a="Скорботна Мла — густий масив боліт просто на схід від Ставка Сліз. Тут патрулюють добірні зелені драконороди й дракончата, що жорстоко відганяють смертних, оберігаючи таємниці Затонулого Храму.",al={"зона драконів болота скорботи","скорботна мла дракони","зелені драконороди болота"}}},fp="16,454,17.720.0,26.592.0,16.542.0,36.265.0,44.301.0,16.273.0,40.245.0,51.306.0,19.225.0"}
P.entries["zone:tanaris"] = {n="Танаріс",s="Танаріс — безмежна спекотна пустеля на півдні Калімдору, край хвилястих піщаних дюн і пекучої спеки. У її серці лежить Ґаджетзан — нейтральне торговельне поселення, яким керують гобліни картелю Стімвідл. За межами гамірних поселень дюни ховають ворожих піщаних тролів, небезпечні вулики силітидів і потаємні володіння бронзового драконячого роду.",h="Танаріс — безмежна спекотна пустеля на півдні Калімдору, край хвилястих піщаних дюн і пекучої спеки.",kw={"танаріс","ґаджетзан","картель стімвідл","зул'фаррак","печери часу","гобліни","пустеля"},ang={["faction:Horde"]="Ґаджетзан — зручний торговельний вузол для розвідників Орди: він з'єднує шляхи від Застави Вільного Вітру й Табору Моджаче з пустками далекого півдня, де кишать силітиди.",["profession:Herbalism"]="Суха спека живить невловимий Вогнецвіт серед рухомих дюн, а затінені руїни й вологі оази дають прихисток цінному Фіолетовому Лотосу.",["profession:Mining"]="Сухі кручі й скелясті виступи довкола дюн багаті на жили мітрилу, справжнього срібла, заліза й золота, а глибше трапляються розкидані поклади малого торію.",["race:Troll"]="Піщана Лють із Зул'Фаррака дає вам змогу побачити своїх давніх родичів, які, відрізані Розколом, змінилися й загартувалися, створивши жорстоку культуру."},sec={{t="Море дюн",b="До того як Великий Розкол розтрощив світ, тут росли буйні джунглі, де жили перші таурени й на які зазіхала Імперія Ґурубаші. Катаклізм позбавив землю лісів, лишивши голу, випалену сонцем пустку. Відрізані зміненою географією, місцеві тролі пристосувалися й загартувалися, ставши племенем Піщаної Люті, і збудували свою відокремлену імперію в обнесеному мурами місті Зул'Фаррак. Нині поверхнею пустелі владарюють гієни, василіски й скорпіди, а під розпеченою землею звиваються підземні тунелі."},{t="Гоблінське підприємство",b="З усього материка Танаріс лежить найближче до рідного острова гоблінів, Кезану, тож картель Стімвідл розгорнув тут процвітаюче підприємство. Від обнесеної мурами оази Ґаджетзан до прибережних доків Порту Стімвідла гобліни суворо дотримуються нейтралітету й радо беруть монети і в Альянсу, і в Орди. Мир тут тримається на кулаках дужих громил, хоча свавільні загрози на кшталт Флібустьєрів Південних морів раз у раз нападають на кораблі й розкопки вздовж узбережжя."},{t="Давні таємниці й нові загрози",b="Піски ховають сили, значно давніші за імперії смертних. На сході лежать Печери часу — прадавні володіння Ноздорму та його бронзового драконячого роду; часом можна побачити, як їхні дракони ширяють у висхідних потоках над пустелею. На півдні величезні кам'яні ворота позначають комплекс титанів Ульдум. Та з підземних гнізд на кшталт Зяючої Безодні й Отруйного Лігва здіймається темніша небезпека: рої силітидів почали прокопуватися назовні по всіх пісках."}},faq={{q="Як дістатися до Танарісу?",a="Мандрівникам треба пройти через Тисячу Голок до Мерехтливих Низин. Гірський прохід, прорубаний у скелях у південному кінці солончаків, веде просто вниз у пустелю, і звідти одразу видно мури Ґаджетзана.",al={"як дістатися до танарісу","дорога до танарісу","вхід у танаріс"}},{q="Чому Ґаджетзан нейтральний до обох фракцій?",a="Ґаджетзаном керує картель Стімвідл, вірний лише прибутку. Щоб торгівля процвітала, а торгові шляхи пустелею були захищені, гобліни суворо дотримуються нейтралітету й наймають вишибал, що лупцюють кожного, кому стане дурості почати бійку між фракціями в міських мурах.",al={"чому ґаджетзан нейтральний","чи орда й альянс можуть у ґаджетзан","гоблінський нейтралітет"}},{q="Що таке Зул'Фаррак?",a="Зул'Фаррак — укріплена пустельна столиця піщаних тролів-фарраків. Відрізане тут відтоді, як Великий Розкол перетворив прадавні джунглі на посушливе пустище, плем'я Піщаної Люті стало ворожим до всіх чужинців і стереже свої священні басейни й таємничі святилища від шукачів пригод.",al={"що таке зул'фаррак","хто живе в зул'фарраку","місто піщаних тролів"}},{q="Що за комахи гніздяться по всій пустелі?",a="Ці комахоподібні звірі — силітиди, страхітливі колоніальні копачі, що будують величезні вулики, як-от Зяюче Провалля й Отруйне Лігво. Їхня поява в Танарісі стривожила спостерігачів на кшталт Старшого Землеміра Фіззлдаузера, нагадавши про прадавні жахіття Війни Рухомих Пісків.",al={"що за комахи в танарісі","вулики танарісу","силітиди танарісу"}},{q="Що за величезними кам'яними дверима на півдні?",a="Монументальна брама в Долині Вартових позначає вхід до Ульдуму — легендарного дослідницького осередку й володіння прадавніх титанів. Вхід надійно запечатаний, його стережуть колосальні кам'яні вартові, а здалеку за ним спостерігають допитливі вчені й гобліни.",al={"гігантські двері півдня танарісу","брами руїн ульдуму","брама титанів танаріс"}},{q="Хто живе в Печерах часу?",a="Печери часу — прадавнє лігво бронзової драконячого роду та її Аспекта, Ноздорму. З цих прихованих звивистих глибин позачасові дракони пильнують плин історії, часом патрулюючи небо високо над південними дюнами.",al={"лор печер часу","що в печерах часу","дракони танарісу"}}},fp="7,385,14.524.0,17.488.0,35.467.0,27.251.0,42.292.0,19.302.0,56.294.0,52.271.0,38.255.0"}
P.entries["zone:teldrassil"] = {n="Тельдрассил",s="Тельдрассил, що означає «Корона Землі», — велетенське нове Світове Дерево, вирощене біля північно-західного узбережжя Калімдору. Виплекане друїдами після Третьої війни, його могутнє гілля тримає на собі цілу сутінкову дику природу й столицю нічних ельфів — Дарнасус. Та під його тихою, залитою місячним світлом кроною почала ворушитися скверна.",h="Тельдрассил, що означає «Корона Землі», — велетенське нове Світове Дерево, вирощене біля північно-західного...",kw={"тельдрассил","світове дерево","нічні ельфи","дарнасус","фандрал стаґгелм","скверна","нордрассил","зона"},ang={["class:Druid"]="Поки Малфуріон ув'язнений у Смарагдовому Сні, Коло Кенарія тут очолює Архідруїд Фандрал Стаґгелм, хоч багато друїдів непокоїться, що Тельдрассил виростили поспіхом.",["faction:Alliance"]="Тельдрассил — найпівнічніший бастіон Альянсу в Калімдорі, що тримає морське сполучення й торгівлю між Дарнасусом і материковими королівствами.",["profession:Herbalism"]="Зовсім позбавлена мінералів і руди, зелена крона дерева надолужує це як рай для збирачів Мирноцвіту, Срібнолисту й Земнокореня.",["race:NightElf"]="Це могутнє дерево — новий початок вашого народу після спустошення Гори Гіджал, але відсутність благословення Аспектів робить його захист нагальним обов'язком."},sec={{t="Крона над морем",b="Тельдрассил — не просто дерево; це піднесена над водами Прихованого Моря жива система. Його велетенські гілки тримають хвилясті пагорби, річки, живлені вранішньою росою, імлисті озера й густі прадавні гаї. На західному краю лежить Дарнасус — велична столиця калдореїв. Біля підніжжя монументального стовбура — Селище Рут'теран, з'єднане з кроною містичною брамою; це головна гавань острова."},{t="Відмова Аспектів",b="Після жертви Нордрассила в Третій війні й таємничого зникнення Шан'до Малфуріона Стормрейджа в Смарагдовому Сні Архідруїд Фандрал Стаґгелм переконав Коло Древніх виростити заміну. Стаґгелм сподівався повернути калдореям утрачене безсмертя. Та Ноздорму й Аспекти драконів визнали цей задум гординею й відмовили в благословенні. Без їхнього життєво важливого захисту ріст Тельдрассила потерпає від неприродних вад."},{t="Недуга, що підкрадається",b="Попри зовнішню велич, молоде Світове Дерево приховує темну хворобу. Місцева живність стала лютою: мирні племена фурболгів упали в божевілля, покручені ґрелли плодяться в курганах, а мерзенні сатири чинять темні обряди в тінях на кшталт Скелі Скверни. Унизу, на берегах Темного Узбережжя, морські велети, трешери й черепахи викидаються на берег, тікаючи від отруєних вод довкола дерева. Натуралісти й вартові тепер гарячково працюють по всьому гіллю, щоб розпізнати тінь, яка повільно душить їхню нову домівку."}},faq={{q="Навіщо виростили Тельдрассил?",a="Коли Нордрассил було спустошено наприкінці Третьої війни, нічні ельфи втратили безсмертя. Архідруїд Фандрал Стаґгелм схилив Коло Древніх і друїдів Кола Кенарія посадити в морі нове Світове Дерево, щоб повернути втрачене їхнім народом.",al={"навіщо створили","хто створив тельдрассил","походження тельдрассила"}},{q="Чому Тельдрассил не повернув нічним ельфам безсмертя?",a="Нордрассил дарував безсмертя, бо його благословив Ноздорму, Позачасний. Коли виростили Тельдрассил, Ноздорму визнав бажання нічних ельфів зухвалим і відмовився дарувати новому дереву своє благословення.",al={"безсмертя","чому не безсмертні","благословення ноздорму"}},{q="Як вийти з Тельдрассила?",a="Мандрівникам треба пройти через Дарнасус до рожевого порталу в Храмових Садах, який переносить униз, до Селища Рут'теран біля підніжжя стовбура. З Рут'терана корабель пливе через море до Обердайна на материку, на Темному Узбережжі; є й маршрути гіпогрифів.",al={"як вибратися","покинути дерево","корабель з тельдрассила"}},{q="Чому в Тельдрассилі немає рудних жил?",a="Уся зона лежить на живих гілках і деревині велетенського Світового Дерева, а не на природній материковій породі. Оскільки тут немає кам'яних підземних шарів, не утворюються ні жили металу, ні поклади руди, зате трави ростуть у великому достатку.",al={"де мідь","немає руди","видобуток у тельдрассилі"}},{q="Чому фурболги й звірі божеволіють?",a="Лиховісна присутність почала просочуватися в неблагословенне коріння Тельдрассила. Хвороба зіпсувала місцеву воду й рослинність, штовхнувши мирних деревляників і плем'я фурболгів-Вузлошкірів у шалену агресію, а рештки сатирів свідомо плекають цю заразу.",al={"зіпсуті фурболги","божевільні вузлошкіри","що за скверна"}},{q="Що таке Тінедол?",a="Тінедол — захищена відлюдна долина на східному гіллі Тельдрассила довкола великого дерева Алдрассил. Це мирне святилище, де молоді нічні ельфи починають навчання, перш ніж вирушити в широкий світ.",al={"тінедол","стартова зона","зона алдрассила"}}},fp="10,340,21.456.0,26.478.0,17.517.1,25.261.0,52.223.0,28.276.0,44.256.0,52.264.0,19.232.0"}
P.entries["zone:thousandneedles"] = {n="Тисяча Голок",s="Тисяча Голок — розлогий каньйон із прямовисних пісковикових стовпів і випалених сонцем солончаків на півдні Калімдору. Таурени чіпляються за поселення на вершинах височенних столових гір, ховаючись від агресивних зграй кентаврів, а гноми й гобліни-винахідники ганяють ракетні автомобілі висохлим морським дном Мерехтливих Низин.",h="Тисяча Голок — розлогий каньйон із прямовисних пісковикових стовпів і випалених сонцем солончаків на півдні...",kw={"тисяча голок","столові гори","кентаври","ґрімтотем","мерехтливі низини","перегони міражу","застава вільного вітру"},ang={["faction:Horde"]="Великий Підйомник з'єднує Пустки з вашою твердинею на Заставі Вільного Вітру й править за стратегічний південний рубіж проти кланів кентаврів і тауренів-бунтівників.",["profession:Engineering"]="Солончаки — місце прощі для майстрів, які прагнуть вивчати ракетне пальне, деталі машин і швидкісну тягу на Перегонах Міражу.",["race:Gnome"]="Перегони Міражу в Мерехтливих Низинах — найкраща нагода показати точність і витонченість гномської інженерії на тлі абияк зліплених гоблінських вигадок.",["race:Tauren"]="Застава Вільного Вітру нагадує, як високо довелося видертися вашому народові, щоб урятуватися від різанини кентаврів, і водночас є плацдармом проти віроломних Ґрімтотемів зі Шпиля Темної Хмари."},sec={{t="Кам'яний ліс",b="До того як Великий Розкол розтрощив прадавній Калімдор, тут був пишний річковий каньйон, який живили внутрішні водні шляхи, що текли до моря. Катаклізм розірвав континент, виштовхнув річище вище від ґрунтових вод і змінив русло річки, тож лишилися тільки сухий камінь і пісковикові шпилі. Нині з дна каньйону здіймаються десятки тонких стовпоподібних колон, наче скам'янілий ліс. Таурени оселилися на вершинах і натягли між ними хиткі мотузяні мости, щоб облаштувати селища поза досяжністю ворожих кентаврів-грабіжників, які никають затіненим дном каньйону внизу."},{t="Небезпеки на столових горах",b="На вершинах голкоподібних шпилів життя зовсім не мирне. На Заставі Вільного Вітру таурени, вірні Орді, протистоять не лише хижим вітряним зміям і вівернам із Високосіду, а й своїм віроломним родичам — войовничому клану Ґрімтотем, що окопався на Шпилі Темної Хмари. Скельний Вартовий Лонггорн керує обороною плато й шукає сміливих бійців, щоб ударити по підбурювачах Ґрімтотем і вберегти хиткі мости між вершинами. На півночі величезні механічні лебідки Великого Підйомника спускають мандрівників із південних Пусток, хоча перейти дно каньйону — і далі смертельний ризик."},{t="Перегони Міражу",b="На південному сході стіни каньйону розступаються, відкриваючи Мерехтливі Низини — величезний висохлий солончак нижче рівня моря. Посеред цієї суворої, сліпучо-білої рівнини гноми й гобліни тримають хиткий нейтралітет довкола Перегонів Міражу. Інженери-суперники Поззік і Фіззл Брассболтс ганяють експериментальні ракетні машини твердою сіллю, щоб з'ясувати, чия раса технічно вправніша. Цей піт-стоп приваблює пройдисвітів, шахраїв на кшталт Кравела Колбірда та мисливців, що полюють на витривалих скорпіонів, черепах і василісків, які никають розпеченою улоговиною."}},faq={{q="Звідки взялася назва Тисяча Голок?",a="Край названо на честь десятків величезних циліндричних шпилів із пісковику, що здіймаються з дна каньйону. Колись, ще до Великого Розколу, їх вирізьбили бурхливі річкові течії, і тепер ці кам'яні вежі схожі на ліс велетенських голок.",al={"чому тисяча голок","походження стовпів-голок","лор шпилів"}},{q="Як спуститися в Тисячу Голок із Пусток?",a="Мандрівники користуються Великим Підйомником — величезним двокабінним ліфтом, яким керують вартові Орди на південному кордоні Пусток. Ступити з краю — вірна смерть, тож платформу треба дочекатися. Мандрівники Альянсу можуть також прийти із заходу, через Таланаар у Фераласі.",al={"як дістатися до тисячі голок","вхід великого підйомника","ліфт до голок"}},{q="Чому таурени живуть на вершинах столових гір?",a="Колись ватаги кентаврів ледь не винищили кочових тауренів. Застави, як-от Застава Вільного Вітру, на неприступних кам'яних стовпах уберігали їх від нападів із землі. Столові гори таурени з'єднали дерев'яними підвісними мостами, щоб пересуватися високо над хижаками й грабіжниками внизу.",al={"чому таврени на стовпах","історія вільного вітру","висота тавренів"}},{q="Що таке Перегони Міражу?",a="Перегони Міражу — випробувальний полігон інженерів на солончаку Мерехтливих Низин. Гномські й гоблінські майстри ганяють рівною сольовою рівниною експериментальні гоночні машини на ракетній тязі, щоб вирішити свою давню суперечку, хто з них будує найкращі машини.",al={"траса солончаків","гонка гномів і гоблінів","ракетна траса"}},{q="Що Ґрімтотеми роблять у каньйоні?",a="Клан Ґрімтотем займає Шпиль Темної Хмари — укріплену групу шпилів просто навпроти Застави Вільного Вітру. На відміну від решти племен тауренів, що присягнули Орді, Ґрімтотеми нападають на інших тауренів і змовляються, щоб захопити владу над столовими горами.",al={"ґрімтотеми тисяча голок","шпиль темної хмари таврени","злі таврени голок"}},{q="Що таке Мерехтливі Низини?",a="Мерехтливі Низини — величезне висохле дно озера на схід від столових гір каньйону. Сольова кірка утворилася, коли прадавнє внутрішнє море випарувалося після Розколу. Пекучий жар, сліпучо-біла сіль і люті хижаки роблять цю пустку непривітною, і нею користуються переважно для швидкісних випробувань машин.",al={"солончак","біла пустеля голок","східна пустеля"}}},fp="16,315,17.605.0,18.606.0,18.558.0,38.246.0,59.275.0,43.301.0,27.259.0,45.264.0,30.290.0"}
P.entries["zone:thunderbluff"] = {n="Тандер Блаф",s="Тандер Блаф — велична столиця тауренів на вітряних червоних столових горах, що здіймаються над травами Малгору. Її заснував Верховний Вождь Кайрн Бладгуф, коли з допомогою Нової Орди об'єднав кочові племена, і нині місто — культурне, духовне й торговельне серце його народу. З'єднане хиткими мотузяними мостами й дерев'яними підйомниками, воно захищає від набігів кентаврів і дарує мирний прихисток мандрівникам з усього Калімдору.",h="Тандер Блаф — велична столиця тауренів на вітряних червоних столових горах, що здіймаються над травами...",kw={"тандер блаф","таурени","кайрн бладгуф","малгор","столиця","узвишшя"},ang={["class:Druid"]="Узвишшя Старійшин — найвище святилище магії природи в Орді на чолі з Верховним Друїдом Гамуулом Рунтотемом, першим за тисячі років тауреном, що навчився друїдства.",["class:Shaman"]="Узвишшя Духів і підземні Ставки Видінь — спокійне осердя, де шанують і чують стихійних духів і духів тауренських предків.",["faction:Horde"]="Значно спокійніший і духовніший за суворі мури Оргріммара, Тандер Блаф — пасторальна опора південного впливу Нової Орди в Калімдорі.",["race:Tauren"]="Тандер Блаф уособлює тяжко здобуту єдність і відродження вашого народу після поколінь кочування й набігів кентаврів — під проводом Верховного Вождя Кайрна Бладгуфа."},sec={{t="Постійний прихисток",b="Незліченні покоління таурени кочували Калімдором, ведучи жорстоку боротьбу за виживання з ненажерливими племенами кентаврів. Ця відчайдушна доба скінчилася в Третій війні, коли Кайрн Бладгуф об'єднав сили з Вождем Траллом. Разом орки й таурени зламали натиск кентаврів і відвоювали соковиті пасовища Малгору. Щоб уберегти своє майбутнє, Кайрн повів союзні племена під захист цих природних кам'яних бастіонів і заснував Тандер Блаф — перший за багато століть спільний, постійний дім тауренів."},{t="Місто в хмарах",b="Тандер Блаф розкинувся на кількох високих столових горах, з'єднаних підвісними мотузяними мостами, і плавно поєднує природну архітектуру з тауренською практичністю. На центральних скелях — гамірні ринки, банк, корчма й височенне гніздовище вітрокрилів, а над прірвою розходяться три окремі гори. Узвишшя Мисливців служить міським розвідникам і слідопитам; на Узвишші Старійшин живуть хранителі переказів і Коло Кенарія на чолі з Верховним Друїдом Гамуулом Рунтотемом; а Узвишшя Духів присвячене духовному єднанню й прихищає шаманів, жерців і таємничі підземні печери, відомі як Ставки Видінь."},{t="Непевна єдність",b="Кайрн Бладгуф має величезну повагу майже серед усіх племен, та правити гордим народом, що лише нещодавно осів, — справа не без тертя. Зокрема, плем'я Ґрімтотем на чолі з хитрою й гострою на язик Старою Відьмою Маґатою Ґрімтотем похмуро тримається на Узвишші Старійшин. Маґата відкрито ставить під сумнів примирливі методи Кайрна та його вірність чужоземним народам Орди. Під пильним оком вождя мир поки тримається, та біля вогнищ ради над рівнинами шепочуть ідейні розбіжності."}},faq={{q="Хто править Тандер Блафом?",a="Тандер Блафом править і веде об'єднані тауренські племена Верховний Вождь Кайрн Бладгуф. Шанований за мудрість, терпіння й величезну силу, Кайрн заснував місто, коли уклав союз з Ордою Тралла й вигнав кентаврів із Малгору.",al={"провідник тандер блафа","хто тут головний","вождь тандер блафа","кайрн"}},{q="Як піднятися до Тандер Блафа?",a="Ті, хто прибуває пішки чи верхи на кодо, мають скористатися величезними дерев'яними підйомниками на південно-західному й північно-східному боках центральної гори. Крім того, у місті є гніздовище вітрокрилів із маршрутами польотів по всьому Калімдору.",al={"підйомник тандер блафа","як потрапити всередину","вхід до тандер блафа","як піднятися"}},{q="Чому таурени будували на високих горах, а не на землі?",a="Століття кочового життя минули під безупинними наскоками войовничих кланів кентаврів. Прямовисні скелі Малгору дають природний захист: вони вберігають оселі, кузні й священних старійшин тауренів від засідок із землі й дають змогу нарешті осісти в мирі.",al={"чому на горах","чому вони на скелях","скелі тандер блафа","таурени на висоті"}},{q="Які є узвишшя в місті?",a="Місто займає центральну гору (поділену на нижній, середній і верхній яруси) та три зовнішні гори довкола неї. Узвишшя Мисливців віддане воїнам, мисливцям і слідопитам. На Узвишші Старійшин живуть друїди, мудреці й плем'я Ґрімтотем. На Узвишші Духів — святині Земної Матері, наставники шаманів, жерців і магів та печерні Ставки Видінь.",al={"райони тандер блафа","що таке узвишшя","квартали тандер блафа"}},{q="Що таке Ставки Видінь?",a="Ставки Видінь — священні підземні печери під Узвишшям Духів. Тауренські провидці, духоходи й знавці чародійства збираються біля цих тихих, оповитих туманом вод, щоб єднатися зі стихіями й тлумачити знамення про майбутнє свого народу.",al={"ставки видінь","печера узвишшя духів","печера тандер блафа"}},{q="Хто така Маґата Ґрімтотем?",a="Маґата Ґрімтотем — матріарх і Стара Відьма грізного клану Ґрімтотем. Вона живе на Узвишші Старійшин і прилюдно бере участь у раді Кайрна, але лишається затятою прихильницею старих звичаїв: не довіряє чужинцям і потай опирається поступливості племені Бладгуф щодо Орди.",al={"маґата","стара відьма","хто провідниця ґрімтотемів"}}},fp="13,473,17.558.0,20.575.0,12.516.1,24.238.0,35.236.0,61.300.0,41.364.0,29.270.0,25.291.0"}
P.entries["zone:tirisfal"] = {n="Галявини Тірісфалю",s="Галявини Тірісфалю — моторошний північний край Лордерона, нині серце володінь Леді Сильвани Віндраннер і Відступників. Під ураженим чумою небом і гнилим гіллям лежать занепалі маєтки, принишклі склепи й величезна підземна столиця — Андерсіті. Оточений безтямною Погибеллю й ревними багряними хрестоносцями, це небезпечний край, де вільна нежить виборює своє виживання.",h="Галявини Тірісфалю — моторошний північний край Лордерона, нині серце володінь Леді Сильвани Віндраннер і...",kw={"галявини тірісфалю","тірісфаль","відступники","лордерон","андерсіті","погибель","багряний хрестовий похід","сильвана","зона"},ang={["class:Priest"]="Тут лежать історичні святині на кшталт Спочинку Фаола — гробниці Архієпископа Алонсуса Фаола, засновника Срібної Длані, — спотворені смертю й спірні між фанатиками та жерцями Тіні.",["faction:Alliance"]="Для вцілілих народів Альянсу Тірісфаль — трагічний пам'ятник падінню Лордерона, повний осквернених гробниць колишніх братів і сестер у вірі.",["faction:Horde"]="Тірісфаль — життєво важливий бастіон Орди на півночі Східних Королівств, що закріплює дипломатичні зв'язки з Відступниками й відбиває людських екстремістів і Погибель.",["race:Undead"]="Це ваша прабатьківська домівка двічі: королівство, яке ви збудували за життя, і хистке святилище, яке мусите боронити в нежитті під рукою Леді Сильвани."},sec={{t="Земля в сутінках",b="Колись родюча колиска людства, Галявини Тірісфалю всохли під прокляттям чуми, яку наслав Король-Ліч. Сонце рідко пробивається крізь каламутний морок, кидаючи вічну хворобливу блідість на вмирущі ліси, занедбані гарбузові грядки й холодні прибережні пагорби. Рештки старих хуторів, як-от Млини Аґаманда й Хутір Балнірів, досі стоять, та їхніх колишніх господарів здебільшого змели в братські могили або підняли неспокійними мерцями. Попри спустошення, край просякнутий темною стійкістю, опертою на такі містечка, як Брілл, і замкнене святилище Похоронного Подзвону, де щойно пробуджені Відступники вчаться витримувати своє друге життя."},{t="Війна на два фронти",b="Хоч Леді Сильвана заявляє про владу над краєм із підземних Руїн Лордерона, Відступники лишаються в облозі з усіх боків. Залишкові раби Погибелі досі заповнюють улоговини, поля й напівзруйновані склепи, цілком покірні крижаному трону Нортренду. На сході фанатичний Багряний Хрестовий Похід зробив північний Тірісфаль своїм головним бастіоном, діючи з Багряного Монастиря. Ревно віддані винищенню кожної істоти нежиті — і живої, і неживої, — їхні застави й патрулі ведуть безперервну партизанську війну проти розвідників Відступників й мирних подорожніх."},{t="Відлуння сивої давнини",b="Задовго до того, як людські королівства коронували перших монархів, Галявини несли давню спадщину. Прадавньою мовою врайкулів «Тірісфаль» означає «Падіння Тіра» — на честь героїчного титана-хранителя Тіра, що бився на смерть із велетенськими космічними жахіттями. У наступні епохи вигнанці-високі ельфи ненадовго спробували оселитися в цих лісах, та тіньові енергії глибоко під землею почали зводити їх з розуму, спонукавши рушити далі на північ. Пізнішими століттями таємна спілка смертних, відома як Рада Тірісфалю, обрала ці тінисті гаї, щоб наділяти силою самотніх Хранителів, які боронили Азерот від демонічного вторгнення."}},faq={{q="Чому небо зелене, а земля гниє?",a="Під час Третьої війни принц Артас і Погибель випустили Чуму Нежиті на Королівство Лордерон. Магічна пошесть отруїла не лише населення, а й ґрунт, дерева та саму воду, лишивши галявини у вічному стані моторошного, хворобливого тління.",al={"чому тірісфаль уражений чумою","що сталося з тірісфалем","чому тірісфаль умирає"}},{q="Яка тут різниця між Відступниками й Погибеллю?",a="Відступники — нежить, що вирвалася з-під телепатичного панування Короля-Ліча після битви біля Гори Гіджал і з власної волі пішла за Леді Сильваною Віндраннер. Погибель, що блукає хуторами й руїнами, лишається безтямними рабами, прив'язаними до наказів Короля-Ліча.",al={"відступники проти погибелі","чому зомбі нападають на нежить","чи вся нежить зла"}},{q="Хто ці вояки в червоних обладунках, що нападають на подорожніх?",a="Вони належать до Багряного Хрестового Походу — безкомпромісного ордену, що відколовся від колишніх паладинів Срібної Длані й уцілілих. Переконані, що вся нежить — невиправна гидота, яку треба очистити мечем і вогнем, вони з фанатичною ненавистю страчують і безтямних рабів, і вільних Відступників.",al={"багряний хрестовий похід","червоні люди","люди з монастиря"}},{q="Звідки походить назва Тірісфаль?",a="Край названо на честь титана-хранителя Тіра. За легендою, Тір упав у битві з потойбічними жахіттями в цій галявині. Прадавньою мовою врайкулів «Падіння Тіра» перетворилося на назву «Тірісфаль», а срібна рука хранителя стала символом, глибоко вплетеним у ранню міфологію людей.",al={"значення тірісфаль","падіння тіра","походження назви тірісфаль"}},{q="Де щойно пробуджені Відступники починають свою путь?",a="Щойно пробуджені Відступники виходять зі склепів Тіньової Могили в Похоронному Подзвоні — замкненому містечку в південно-західному Тірісфалі. Там управителі й екзекутори оцінюють, чи мають воскреслі мерці здоровий глузд і вірність, потрібні для служби Темній Леді.",al={"стартова зона нежиті","де похоронний подзвін","стартова зона відступників"}},{q="Як мандрівники залишають Тірісфаль, щоб дістатися інших континентів?",a="Велика гоблінська вежа цепелінів стоїть на схилі пагорба на південь від Брілла, одразу за Руїнами Лордерона. Ці повітряні кораблі регулярно й напряму перевозять через моря до Оргріммара в Калімдорі та Базового Базового Табору Ґром'ґол у Долині Стренглторну.",al={"цепеліни тірісфалю","як дістатися до оргріммара","як дістатися до стренглторну"}}},fp="15,403,18.637.0,19.603.0,26.621.0,42.269.0,65.287.0,53.289.0,39.297.0,53.269.0,53.247.0"}
P.entries["zone:undercity"] = {n="Андерсіті",s="Глибоко під розтрощеними руїнами Столиці Лордерона лежить Андерсіті — темна твердиня Відступників. Спершу Погибель висікла її з давніх королівських склепів і темниць, але Леді Сильвана Віндраннер захопила місто й перетворила на неприступне підземне святилище. Нині це осідок влади Відступників і важливий оплот Орди на півночі Східних Королівств.",h="Глибоко під розтрощеними руїнами Столиці Лордерона лежить Андерсіті — темна твердиня Відступників.",kw={"андерсіті","відступники","сильвана","лордерон","столиця","погибель","орда"},ang={["faction:Horde"]="Як головний плацдарм Орди у Східних Королівствах, Андерсіті забезпечує прямі рейси цепелінів до Дуротару й Базового Базового Табору Ґром'ґол.",["race:Human"]="Під землею вашого полеглого прадавнього королівства лежить похмуре спотворення королівських склепів Лордерона, де тепер бродять ходячі трупи ваших колишніх братів.",["race:Orc"]="Глибоко в цих самих темницях Альянс Лордерона колись тримав легендарного Вождя Оргріма Думхаммера, поки той не здійснив свою історичну втечу.",["race:Undead"]="Андерсіті — ваше суверенне святилище й батьківщина, висічена вашими власними руками після того, як ви зламали залізну хватку Короля-Ліча на своєму розумі."},sec={{t="Від королівських склепів до твердині Погибелі",b="Задовго до того, як чума прокотилася Лордероном, катакомби, темниці й каналізацію під палацом разом називали Андерсіті. Тут були гробниці знаті, найглибші в'язниці королівства — де колись тримали колишнього Вождя Оргріма Думхаммера, поки він не втік, — і найбідніші мешканці держави. Коли 20 року після відкриття Темного Порталу Артас Менетіл убив короля Теренаса й спустошив столицю, принц наказав своїм слугам-нежиті розкопати й розширити підземні ходи, перетворивши їх на укріплений осідок влади Погибелі."},{t="Постання Відступників",b="Погибель так і не побачила свою темну столицю завершеною. Коли після битви на Горі Гіджал сили Короля-Ліча ослабли, Леді Сильвана Віндраннер вирвалася з-під влади його колективного розуму й повела за собою тисячі нежиті. Вона заманила Артаса в засідку й відкинула його назад до Нортренду. Після запеклої тристоронньої громадянської війни з рештками Погибелі, жахолордами й людським спротивом Сильвана захопила недобудовані катакомби. Назвавши свій народ Відступниками, вона роками керувала роботами, що завершили розлоге підземне місто."},{t="Архітектура проклятих",b="Андерсіті збудовано концентричними кільцями, поділеними на квартали з різним призначенням. У самому серці — Торговий Квартал, сполучений великими підйомниками з руїнами палацу нагорі. Довкола нього — Воєнний Квартал, Квартал Розбійників, Магічний Квартал і отруйний Апотекаріум, де Королівське Аптекарське Товариство варить згубні чуми біля каналів, сповнених зеленого слизу. Ще глибше лежить Королівський Квартал, де Королева Баньші тримає двір разом зі своїм командувачем, повелителем жаху Варіматрасом, під охороною легіонів височенних гидот."}},faq={{q="Чим було Андерсіті до того, як його захопила нежить?",a="Під палацом Лордерона лежали давні склепи людських королів, а також міські темниці й величезна мережа каналізації. Тут тримали воєнних полонених, зокрема Оргріма Думхаммера, а в підземних тінях жили злиденні городяни. Сплюндрувавши столицю, принц Артас почав перетворювати ці катакомби на фортецю Погибелі, але Сильвана їх захопила.",al={"походження андерсіті","чим було андерсіті спершу","історія каналізації лордерона"}},{q="Чому місто збудоване під землею, а не на поверхні?",a="Наземне місто Лордерон у Третій війні було вщент зруйноване, і його було важко боронити від Багряного Хрестового Походу, сил Погибелі й уцілілих людей з Альянсу. Підземні тунелі давали природні укріплення, вузькі проходи й потаємність, тож Відступники змогли завершити розпочате Погибеллю будівництво й непомітно процвітати.",al={"чому жити під землею","чому не відбудувати лордерон","чому андерсіті під руїнами"}},{q="Хто править Андерсіті?",a="Містом править Леді Сильвана Віндраннер — Королева Баньші й королева Відступників. Вона править із Королівського Кварталу під охороною королівських вартових-Відступників і свого підкореного поплічника, жахолорда Варіматраса.",al={"хто провідник андерсіті","правитель андерсіті","хто керує андерсіті"}},{q="Що за пам'ятник королю Теренасу в руїнах нагорі?",a="Над головними підйомниками міста стоїть кам'яний пам'ятник убитому королю Теренасу Менетілу Другому. Його тіла там немає: труп короля спалили, а попіл розвіяли під час воскресіння Кел'Тузада. Уцілілі люди Альянсу відважно вирізьбили цей пам'ятник серед руїн, щоб пам'ять про останнього справжнього короля Лордерона жила далі.",al={"гробниця короля теренаса","могила в тронній залі лордерона","хто збудував гробницю над андерсіті"}},{q="Що за дивні звуки в тронній залі Лордерона?",a="У зруйнованій тронній залі над підйомниками Андерсіті досі живуть примарні відлуння минулого. Хто стане посередині, почує ледь чутні привидні звуки: святкові дзвони й шелест пелюсток троянд на честь повернення Артаса, застережливі слова пророка Медіва й останню розмову короля Теренаса з сином-батьковбивцею.",al={"привидні звуки в тронній залі","шепіт у тронній залі","голоси в тронній залі лордерона"}},{q="Чому Відступники пускають сюди інших членів Орди?",a="Відступники уклали союз із розрахунку з Ордою Вождя Тралла, щоб вижити, адже довкола них — ворожі фанатики Багряного Хрестового Походу й легіони Погибелі. Живим расам Орди отруйні випари й алхімічні ріки не дають дихати, та посланцям і мандрівникам дозволяють сюди приходити, щоб зміцнювати дипломатичні й військові зв'язки.",al={"чому орки в андерсіті","орда в андерсіті","чому андерсіті в орді"}}},fp="9,400,36.527.0,20.525.0,26.518.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Кратер Ун'Ґоро",s="Кратер Ун'Ґоро — первісні джунглі в глибокій западині між посушливими пустками Танарісу й Силітусу. Тут панують дикі динозаври, живі елементалі й вулкан у самому центрі, а пишна кальдера сповнена давніх реліквій Титанів і кристалів сили, чиє походження досі лишається глибокою таємницею.",h="Кратер Ун'Ґоро — первісні джунглі в глибокій западині між посушливими пустками Танарісу й Силітусу.",kw={"кратер ун'ґоро","дияволозаври","кристали сили","притулок маршала","титани","хребет вогняного шлейфу","пілони"},ang={["class:Druid"]="Друїди Кола Кенарія вивчають відокремлену екосистему Ун'Ґоро й беруть його багатий ґрунт, щоб вирощувати Ранкозерно, прагнучи збагнути чисту, неприборкану життєву силу, що живить кальдеру.",["faction:Alliance"]="Природознавці Альянсу гуртуються довкола Віллідена Маршала й Дж. Д. Коллі в Притулку Маршала, поспішаючи розгадати пілони Титанів і водночас охороняючи дослідників із Дарнасуса, що збирають зразки ґрунту.",["faction:Horde"]="Шукачі пригод з Орди часто прибувають через Танаріс, щоб помірятися силою з легендарними дияволозаврами й допомогти травникам Тандер Блафа вирощувати Ранкозерно з первісної землі Ун'Ґоро.",["profession:Herbalism"]="Багата волога западини живить рідкісні рослини: це одне з небагатьох місць Калімдору, де поряд ростуть Сліпотрав, Снолист і Золотий Сансам, а на схилах вулкана — Вогнецвіт.",["profession:Mining"]="Стрімкі стіни кратера й скелі Хребта Вогняного Шлейфу рясніють покладами мітрилу й жилами багатого торію, тож край — одне з найкращих місць для видобутку цінної руди."},sec={{t="Землі Богів",b="Затиснутий між пустелями, Кратер Ун'Ґоро кидає виклик географії південного Калімдору. Давні записи нічних ельфів про Війну Рухомих Пісків свідчать, що комахоподібних кіраджі спинили на краю кратера: вони не змогли проникнути в місце, яке їхньою мовою звалося «Землями Богів». Учені припускають, що кальдера була полігоном чи давньою оселею Титанів, коли ті творили Калімдор. Уздовж хребтів здіймаються кам'яні пілони, що гудуть від енергії, а крізь первісну землю проростають сині, червоні, зелені й жовті кристали."},{t="Дика екосистема",b="В Ун'Ґоро немає ні міст, ні селищ, ні корінних гуманоїдних спільнот. Натомість тут вирує неприборкане первісне життя. Дияволозаври, найгрізніші хижаки краю, нишпорять рівнинами Стежки Жаху, хижі кривавопелюстки шмагають усе довкола на болотах, а слизуни повзають смоляними ямами Лаккарі. У серці кратера височіє Хребет Вогняного Шлейфу — діючий вулкан, де кишать ворожі вогняні елементалі на чолі з істотою на ім'я Полум'яний бігун. Для дослідників і шкурників западина — небачене природне багатство, зокрема жадані шкури дияволозаврів, якщо, звісно, вдасться самому не стати чиєюсь здобиччю."},{t="Притулок Маршала",b="Цивілізація в кратері зводиться майже лише до Притулку Маршала — табору на висоті, у північних кручах. Експедиція вчених, природознавців і шукачів удачі на чолі з Вілліденом Маршалом намагалася описати скарби западини, та потворні звірі потріпали її й загнали на висоту. Нині притулок — обложений перевалочний пункт для відважних мандрівників, що вивчають загадкові кристали сили кратера, наносять на мапи вулканічну активність і пильно стежать за роями силітидів, які проривають південні хребти."}},faq={{q="Як потрапити в Кратер Ун'Ґоро?",a="У кратер ведуть природні спуски по його стінах: один — із південно-західного кута Танарісу біля Долини Будякових Кущів, другий — із північного сходу Силітусу. Нерозважливі шукачі пригод іноді стрибають зі скель, але без магії таке падіння смертельне. Притулок Маршала на півночі має польоти до Ґаджетзана й Цитаделі Кенаріуса.",al={"як зайти в ун'ґоро","вхід в ун'ґоро","як дістатися до кратера ун'ґоро"}},{q="Для чого кольорові кристали сили?",a="По всіх джунглях розкидані червоні, сині, зелені й жовті Кристали Сили. За допомогою гнома-дослідника Дж. Д. Коллі з Притулку Маршала дослідники можуть розшифрувати, як користуватися цими кристалами на Північному, Східному й Західному Пілонах. Поєднуючи певні кольори на відповідних пілонах, можна приборкати приховану енергію Титанів і виготовити захисні чи цілющі обереги.",al={"кристали ун'ґоро","червоні сині зелені жовті кристали","пілони сили"}},{q="Чому Ун'Ґоро такий буйний, хоч його оточують пустелі?",a="Учені вважають, що неприродна буйність Ун'Ґоро штучна й походить від Титанів, які творили світ. Титанічні провідники, тепло вулканічної діяльності Хребта Вогняного Шлейфу й прадавня енергія силових ліній живлять відокремлену, надзвичайно прискорену екосистему, що опирається посушливому клімату сусідніх Танарісу й Силітусу.",al={"чому ун'ґоро джунглі","зв'язок ун'ґоро з пустелею","як в ун'ґоро рослини"}},{q="Чому кіраджі називали це місце «Землями Богів»?",a="Згідно з табличками часів Війни Рухомих Пісків, рої комах зупинили свій наступ на порозі кратера. Геолог Ларксбейн, що переклав цей запис, пов'язує назву з гіпотезами, що в кратері колись жили Титани, і припускає, чи не пильнував Землі Богів сам Аман'Тул.",al={"земля богів значення","кіраджі ун'ґоро","чому силітиди не взяли ун'ґоро"}},{q="Для чого потрібен Ґрунт Ун'Ґоро?",a="По всьому кратеру лежать купи багатої, родючої землі. Зібраний ґрунт разом із насінням Тарлендріса у Вічнозеленій Торбинці дає змогу виростити Ранкозерно — містичну траву, яку дуже шукають дослідники з Тандер Блафа, Дарнасуса й Кола Кенарія.",al={"зразок ґрунту ун'ґоро","що робить ґрунт ун'ґоро","ґрунт ун'ґоро"}},{q="Чи є тут поселення людиноподібних чи підземелля?",a="У Кратері Ун'Ґоро немає ні підземель, ні корінних людиноподібних громад. Єдине постійне поселення — Притулок Маршала, невелика застава експедиції на північному краю. Окрім поодиноких мисливців-відлюдників чи заблукалих дослідників, решта кальдери цілком дика.",al={"підземелля ун'ґоро","хто живе в ун'ґоро","людиноподібні ун'ґоро"}}},fp="14,289,13.564.0,18.559.0,16.579.0,35.395.0,45.390.0,56.325.0,51.316.0,30.275.0,52.274.0"}
P.entries["zone:wailing"] = {n="Печери Стогонів",s="Під Оазою Буйних Вод у посушливих Пустках лежать Печери Стогонів — заплутана система підземних джерел і розколин, названа так через моторошний свист пари, що виривається з-під каменю. Те, що починалося як шляхетна спроба друїдів відродити вибілену сонцем савану Калімдору, обернулося на спотворений, отруйний підземний світ. Тепер печери кишать спотвореними звірами й занепалими учнями, яких зіпсувало глибоке протиприродне жахіття.",h="Під Оазою Буйних Вод у посушливих Пустках лежать Печери Стогонів — заплутана система підземних джерел і...",kw={"печери стогонів","наралекс","друїди ікла","смарагдове жахіття","мутанус пожирач","пустки","підземелля"},ang={["class:Druid"]="І для друїдів кенарійської традиції, і для тих, хто йде тауренським шляхом, печери — трагічне застереження про небезпеки Смарагдового Сну та урочистий обов'язок очистити світ від занепалих побратимів — Друїдів Ікла.",["race:NightElf"]="Наралекса шанували серед друїдів нічних ельфів, і трагедія його падіння через Смарагдове Жахіття — болюча катастрофа для його родичів за морем.",["race:Tauren"]="Спотворені води загрожують тендітним оазам, що живлять життя в усіх Пустках, тож очищення джерел украй важливе для племен Малгору та Перехрестя."},sec={{t="Шляхетне видіння, що стало отрутою",b="The night elf druid Naralex originally discovered this vast water system and devised an ambitious design: by opening a conduit straight into the Emerald Dream, he would siphon pure primal life essence through the subterranean springs, transforming the parched Barrens back into a thriving, verdant paradise. Deep within the caverns, Naralex slipped into communion with the Dream, anchored by his loyal acolytes. Tragically, rather than tapping into pure vitality, the druid's sleeping mind touched the Emerald Nightmare. The festering corruption instantly seized him, transforming his well-intentioned conduit into a valve pouring venom and madness into the underground waterways."},{t="Друїди Ікла",b="Коли темна сила Жахіття почала струменіти від безпорадного тіла Наралекса, його учні піддалися божевіллю. Зрікшись спокійної мудрості Кола Кенарія, вони утворили фанатичну секту Друїдів Ікла. Прибравши плазуючої подоби, ватажки секти — Леді Анакондра, Лорд Кобран, Лорд Пайтас і Лорд Серпентіс — тепер не борються з отруйною мутацією печер, а віддаються їй. Вони пильно оберігають свого сплячого наставника від будь-якого втручання ззовні, вірячи, що це спотворене буяння і є справжня еволюція природи."},{t="Жахіття у плоті",b="Зламати владу Друїдів Ікла ще не означає врятувати Наралекса. Коли його вцілілі, незіпсовані учні починають біля Скелі Сновидця обряд, щоб обережно вивести його з трансу, сплячий ельф у муках підсвідомості несамовито вивергає свій найглибший жах. Істота, що вихоплюється назовні, — жахливий, потворний мурлок на ймення Мутанус Пожирач — це тілесне втілення найгірших кошмарів Наралекса. Лише вбивши цю гидоту, можна розірвати зв'язок із Жахіттям, і тоді Наралекс прокинеться, обернеться птахом і полетить геть зі зіпсованих печер."}},faq={{q="Чому вони звуться Печерами Стогонів?",a="Печери дістали назву від журливих, виючих звуків, що лунають тунелями. Ці звуки виникають природно, коли підземні струмені пари й потужні пориви вітру проштовхуються крізь вузькі тріщини у вапняку.",al={"чому печери стогонів","походження назви","чому вони стогнуть"}},{q="Чому звірі всередині стали «девіантними»?",a="Коли Наралекс потрапив під владу Смарагдового Жахіття, отруйна енергія сну просочилася просто в підземні джерела. Життя в цих заражених водах і пиття з них перетворили звичайних рапторів, кроколісків і змій на неприродні «девіантні» різновиди.",al={"скверна збочених","чому раптори мутанти","походження збочених звірів"}},{q="Хто такі Друїди Ікла?",a="Колись це були віддані учні Наралекса — нічні ельфи й таурени. Спотворені разом із ним Жахіттям, вони втратили розум і викривили своє друїдське мистецтво на поклоніння зміям і отруті, взявши собі імена на кшталт Кобран, Пітас і Анакондра.",al={"друїди ікла","лор друїдів ікла","хто серпентіс"}},{q="Чому останній бос — велетенський мурлок на ім'я Мутанус?",a="Мутанус з'являється під час спроби пробудити Наралекса. Його природа й зв'язок зі сплячим друїдом розкриваються в ході ритуалу.",al={"чому мутанус мурлок","що таке мутанус","лор останнього боса"}},{q="Що станеться після перемоги над Мутанусом?",a="Після сутички учень і далі намагається пробудити Наралекса. Доля друїда розкривається наприкінці ритуалу.",al={"пробудження наралекса","кінцівка наралекса","що буде з наралексом"}},{q="Хто живе в печері над входом до печер?",a="У скелі над входом, схожій на очницю черепа, отаборилися вірні Колу Кенарія друїди, зокрема Налпак і Ебру. Вони шукають відважних мандрівників, щоб ті здобували шкури девіантних звірів і очищали спотворення, поки воно не поглинуло всі Пустки.",al={"печера над входом","нпс змієвого черепа","хто налпак та ебру"}}},fp="15,426,31.680.0,22.528.0,24.592.1,37.248.0,50.267.0,31.252.0,51.137.1,39.130.1,52.232.0"}
P.entries["zone:westernplaguelands"] = {n="Західні Чумні Землі",s="Колись родюча житниця північного Лордерону, Західні Чумні Землі нині задихаються під отруйним туманом і легіонами нежиті. Хоча казани Кел'Тузада занапастили тутешні ферми й містечка, ґрунт і досі вперто тримається за життя. Срібний Світанок, Альянс, Відступники й Багряний Хрестовий Похід ведуть на цих сплюндрованих полях відчайдушну боротьбу.",h="Колись родюча житниця північного Лордерону, Західні Чумні Землі нині задихаються під отруйним туманом і...",kw={"західні чумні землі","андоргал","гартглен","сколомансія","гробниця утера","чумні казани","табір студеного вітру"},ang={["class:Paladin"]="Осквернені поля Лордерону — скорботне випробування для святих воїнів: тут і паломництво до Гробниці Утера, і праведна війна з жахіттями Сколомансії та спотвореними фанатиками Гартглена.",["faction:Alliance"]="Табір Студеного Вітру — передовий гарнізон Альянсу, де Командир Ашлам Валорфіст керує походами, щоб знищити чумні казани й помститися за загиблі міста Лордерону.",["faction:Horde"]="Заслон позначає рубіж володінь Відступників; звідси Орда просувається на схід, щоб знешкодити командирів Погибелі й дати відсіч багряним фанатикам на своєму вразливому фланзі.",["profession:Herbalism"]="Скверна, що досі тут лишається, робить край одним із небагатьох місць, де серед спотворених соснових гаїв можуть укорінитися рідкісні й небезпечні рослини на кшталт Чумоцвіту й Сліз Артаса."},sec={{t="Житниця Лордерону",b="До Третьої війни цей край був зеленим поясом ферм, що тягнувся на схід від Галявин Тірісфалю до Озера Дарроумер. Гартглен правив північчю з Фортеці Марденгольд, а розлоге місто Андоргал порядкувало зберіганням і вивезенням зерна по всьому королівству. Саме через цю важливу роль житниці край став головною ціллю Кел'Тузада. Підмішавши Чуму Нежиття просто в зерно, яке відвантажували з Андоргала, Культ Проклятих обернув хліб Лордерону на його погибель."},{t="Край в облозі",b="Щоб отруїти ґрунт назавжди, Погибель поставила чотири величезні чумні казани в найбільших маєтках: на Полі Скверного Каменю, у Сльозах Далсона, у Звивистому Лігві та у Всиханні Гаррона. Нині біля цих смердючих чанів порядкують жахливі Володарі Казанів, що виганяють у повітря отруйний туман. Довколишні дерева скручуються від набряклих, пухлинних наростів, а спотворені звірі шаленіють у хащах. Під Каер Дарроу на Озері Дарроумер Темний Майстер Ґандлінґ навчає некромантів у Сколомансії, ще більше посилюючи загрозу нежиті."},{t="Розділені фракції",b="Попри всюдисущу Погибель, кілька фракцій утримують тут обложені опорні пункти. Багряний Хрестовий Похід контролює фортецю Гартглен на півночі, з шаленою ревністю винищуючи все, що вважає зараженим. На півдні сили Альянсу діють із Табору Студеного Вітру, а Відступники обороняють свої кордони біля Заслону. Боротьбу з казанами нежиті спрямовує й узгоджує нейтральний Срібний світанок, що допомагає героям обох фракцій і охороняє Гробницю Утера — останню справді освячену землю в краї."}},faq={{q="Чому чума вдарила по цьому краю так сильно?",a="Андоргал був сільськогосподарським торговим вузлом північного Лордерона. Кел'Тузад навмисно вдарив по місцевих запасах: заразив зерносховища й поставив величезні чумні казани на чотирьох великих фермах, щоб швидко поширити нежиття продовольчими поставками по всьому королівству.",al={"чому чума вдарила сильно","чому андорґал","чому тут казани"}},{q="Хто контролює Гартглен на півночі?",a="Гартгленом і його фортецею, Фортецею Марденгольд, править Багряний Хрестовий Похід. Колись це був місцевий адміністративний осередок Лордерона, а тепер фанатики страчують усіх чужинців, що наближаються до їхніх меж, підозрюючи кожного, хто не належить до хрестоносців.",al={"фракція гартглена","хто в марденгольді","чи гартглен дружній"}},{q="Де гравці Альянсу й Орди можуть знайти безпечні застави?",a="Альянс тримає Табір Студеного Вітру біля південного кордону з Горами Альтерак: там є розпорядник польотів і союзники зі Срібного Світанку. Орда діє з Бастіону на західному кордоні, біля входу з Галявин Тірісфалю.",al={"де польоти","табір орди зчз","табір альянсу зчз"}},{q="Для чого чумні казани на полях?",a="Ці казани, які Культ Проклятих поставив на Полі Скверного Каменю, у Сльозах Далсона, на Гнітючому полі й у Всиханні Гаррона, безперервно випускають чумні випари в повітря й ґрунт. Агенти Срібного Світанку наймають шукачів пригод, щоб убивати Володарів Казанів і створювати протидію отруйним зіллям.",al={"що за казани","призначення казанів","казан скверного каменю"}},{q="Що таке Сколомансія і де вона?",a="Сколомансія — підземна академія некромантії, яку тримають Погибель і Культ Проклятих. Вона схована під руїнами Каер Дарроу — острівної фортеці в південно-східних водах Озера Дарроумер.",al={"місце сколомансії","де сколомансія","підземелля кер дарроу"}},{q="Чи є в Західних Чумних Землях незіпсовані місця?",a="Гробниця Утера на Пагорбі Скорботи біля південного краю лишається цілком святою й не зачепленою пошестю. Вона стоїть як освячений пам'ятник полеглому Верховному Генералові Утерові Світлоносцеві й утраченому Ордену Срібної Длані.",al={"свята земля чумних земель","чи гробниця утера чиста","чи безпечна гробниця утера"}}},fp="19,377,28.525.0,18.542.0,16.525.0,41.284.0,37.251.0,56.229.0,58.284.0,44.220.0,51.244.0"}
P.entries["zone:westfall"] = {n="Вестфол",s="Колись Вестфол був родючою житницею Королівства Стормвінд, а тепер це вітряний, занедбаний край, захоплений розбійниками. Без підтримки Корони й без військових гарнізонів уцілілі хуторяни чіпляються за свої ферми, а Братство Дефіас дедалі міцніше стискає хватку з покинутого гірницького містечка Мунбрук.",h="Колись Вестфол був родючою житницею Королівства Стормвінд, а тепер це вітряний, занедбаний край, захоплений...",kw={"вестфол","братство дефіас","мунбрук","народне ополчення","сентінел гілл","мертві копальні","едвін венкліф"},ang={["class:Rogue"]="Тіньова війна у Вестфолі зіштовхує шпигунів SI:7 віч-на-віч із тямущими розвідниками, злодіями й убивцями Братства Дефіас.",["faction:Alliance"]="Якби не Народне ополчення, що тримає Сентінел Гілл, Братство Дефіас контролювало б південні підступи аж до Лісу Елвінн.",["profession:Cooking"]="Знесилені хуторяни Ферми Салдина обходяться жорсткою місцевою дичиною й навчають мандрівників варити ситну страву, відому як Вестфоллське Рагу.",["race:Human"]="Вестфол — болісне відображення політичного розкладу Стормвінда: фермерів, що голодують у пилюці, покинула та сама знать, яку вони годували своєю працею."},sec={{t="Покинутий край",b="Поколіннями Вестфол годував Королівство Стормвінд. Його пологі пасовища й пшеничні лани квітнули, аж поки наслідки Другої війни не принесли фінансового виснаження та політичної байдужості. Королівство спрямовувало ресурси деінде й не утримувало гарнізонів, і край занепав. Нині безплідні пасовища, виття морських вітрів, збунтовані големи жнив та набіги гнолів Річколапів роблять кожен день випробуванням для тих небагатьох упертих, хто відмовляється покинути свої хутори."},{t="Піднесення Братства",b="Крах Вестфолу пришвидшився, коли Гільдія Каменярів, якій не заплатили за відбудову Стормвінда, підняла відкритий заколот. Оголошені поза законом і вигнані, каменярі на чолі з Едвіном Венкліфом перетворилися на Братство Дефіас. Вони обрали Вестфол своєю твердинею: палили поля впертих фермерів, засолювали землю й захоплювали покинуті шахти. Тепер Братство, засівши в місті-примарі Мунбруку, фактично править більшою частиною краю — хіба що без титулу."},{t="Народне ополчення",b="Дім Вельмож не зважав на біду Вестфолу, тож місцеві мешканці взялися захищатися самі. На укріпленій заставі Сентінел Гілл Ґраян Стаутмантл зібрав Народне ополчення — загін добровольців, що намагається стримати гнолів і бандитів. Регулярних вояків і припасів зі Стормвінда немає, тож Ополчення покладається на мандрівних шукачів пригод, щоб відкинути хвилю Дефіас і вберегти ферми, що ще лишилися."},{t="Змова Мертвих Копалень",b="Справжній розмах загрози Дефіас прихований під землею. Глибоко в покинутих золотих шахтах Мертвих Копалень під Мунбруком Едвін Венкліф зібрав військо з головорізів, гоблінів і ренегатів. Це вже не просто розбій: Братство будує величезний броненосець, що має піднятися вздовж узбережжя й обстріляти Стормвінд просто з моря."}},faq={{q="Чому у Вестфолі стільки покинутих ферм?",a="Стормвінд вивів свої гарнізони, коли їхнє утримання стало надто дорогим, і край лишився без захисту. Невдовзі Братство Дефіас захопило сільську місцевість: прогнало хуторян, спалило поля й перепрограмувало механічних наглядачів урожаю на смертоносних вартових.",al={"покинуті ферми","чому вестфолл мертвий","чому поля порожні"}},{q="Чому Стормвінд не посилає війська на допомогу Вестфолу?",a="Скарбниця королівства виснажена, а Дім Вельмож вважає загрози в інших краях важливішими. До того ж придворні маніпуляції потай позбавили Вестфол уваги й припасів, і місцеві мешканці мусять цілком самі давати собі раду.",al={"чому немає армії стормвінда","де вартові","допомога стормвінда"}},{q="Що таке Народне ополчення?",a="Народне ополчення — добровольча самооборона, яку зорганізував Ґраян Стаутмантл на Сентінел Гіллі. Оскільки корона відмовилася посилати у Вестфол вояків, фермери й поселенці, що лишилися, об'єдналися, щоб відбиватися від Братства Дефіас і гнолів-Річколапів.",al={"народне ополчення","ополчення сентінел гілла","армія ґріана стаутмантла"}},{q="Хто очолює Братство Дефіас у Вестфолі?",a="Едвін Венкліф, колишній голова Гільдії Каменярів, що керував відбудовою Стормвінда. Після гіркої суперечки про платню, що закінчилася заворушеннями й загибеллю королеви Тіффін, Венкліф повів своїх робітників у Вестфол і вдався до збройного заколоту.",al={"лідер дефіасу","хто веде дефіас","венкліф"}},{q="Що сховано в Мунбруку?",a="Під непримітною стодолою в Мунбруку лежить вхід до Мертвих Копалень — величезної покинутої золотої копальні, яку Братство Дефіас перетворило на підземну фортецю й корабельню для війни зі Стормвіндом.",al={"таємниця мунбрука","що в мертвих копальнях","шахта мунбрука"}},{q="Чому механічні опудала нападають на людей?",a="Спочатку цих механічних наглядачів урожаю збудували, щоб доглядати поля й відлякувати шкідників, але гоблінські майстри, пов'язані з Дефіас, захопили й переробили їх, щоб ті патрулювали поля й убивали всіх непроханих гостей.",al={"жнивні големи нападають","стражі врожаю","злі опудала"}}},fp="8,337,18.502.0,27.479.0,20.427.0,24.379.1,44.289.0,52.262.0,29.269.0,45.267.0,32.226.1,51.200.0"}
P.entries["zone:wetlands"] = {n="Багнокрай",s="Багнокрай — величезне, оповите туманом болото між горами Каз Модану та берегами Затоки Барадін. Споконвіку терзаний війнами дворфів і навалами орків, він править за суворий буферний край між Айронфорджем і північними землями Лордерону. Укріплений порт Гавань Менетіл — головна рятівна нитка Альянсу в цій розмоклій глушині, яку заполонили орки Драконячої Пащі, мурлоки й гноли.",h="Багнокрай — величезне, оповите туманом болото між горами Каз Модану та берегами Затоки Барадін.",kw={"багнокрай","гавань менетіл","ґрім батол","драконяча паща","дун модр","темне залізо","болота"},ang={["faction:Alliance"]="Гавань Менетіл — головні глибоководні ворота Альянсу через Велике Море, що поєднують королівства сходу з експедиційними заставами в Калімдорі.",["profession:Mining"]="Пагорби й печерні глибини Каменя Тельґен приховують багаті рудні жили, зокрема рідкісні поклади інцендицитової руди, якої так прагнуть дворфійські гірники й інженери.",["race:Dwarf"]="Для дворфів Багнокрай — місце гірко-солодких спогадів: тут втрачено Дун Модр, тут сталася давня трагедія Ґрім Батолу, і тут досі тривають труди з оборони торгового шляху короля Маґні на північ."},sec={{t="Край води й руїн",b="Багнокрай, що простягається під височенним урвищем Каменетесної Греблі, — холодний, підтоплений простір, оповитий вічним туманом під одноманітним сірим небом. Колись тут квітли дворфійські поселення, а тепер болота всіяні затонулими кам'яними руїнами, розмоклими трясовинами й підступними драговинами. Шукачам пригод доводиться пробиратися вузькими проходами: або рухатися на північ з Лох Модану крізь забарикадовану ущелину Дун Алґаз, або перейти височенні арки Мосту Тандол з Аратійського нагір'я."},{t="Шрами Ґрім Батолу",b="Над східними околицями боліт похмуро нависає Ґрім Батол — колишня твердиня Вайлдгаммерів. Осквернена під час Війни Трьох Молотів, у Другу війну вона стала укріпленим сховком клану Драконячої Пащі. Коли червоні дракони вирвалися з орківського полону, їхня вогняна помста розгромила орківські сили й спустошила довколишні схили. Нині червоні драконорідні стережуть Брами Драконячої Пащі від будь-яких непроханих гостей, а здичавілі рештки клану Драконячої Пащі живуть у розкиданих по пагорбах таборах і далі нападають на мандрівників по всіх болотах."},{t="Порт західного узбережжя",b="Гавань Менетіл, що примостилася на березі Затоки Барадін, — живе серце торгівлі та постачання Альянсу в Каз Модані. Названий на честь короля Теренаса Менетіла II, цей стійкий порт поєднує Східні Королівства з далеким Калімдором: звідси регулярно ходять кораблі до Обердайна й Острова Терамор. Попри стратегічну військову вагу та міцну дворфійську архітектуру, гавані повсякчас загрожують прибережні мурлоки, болотяні істоти й морські розбійники, що полюють на судна в скелястих протоках."},{t="Обложені рубежі",b="Багнокрай — справжня зона бойових дій на кількох фронтах. На далекій півночі дворфи Темного Заліза під проводом чорнокнижника Балґараса Мерзенного підірвали Міст Тандол і захопили містечко Дун Модр, перерізавши сухопутні обози з припасами. Тим часом мохошкірі гноли безчинствують на центральних драговинах, загрожуючи навіть прадавнім охоронцям на кшталт Ретіеля Зеленовартового. Між свавільними загонами орків, лазутчиками Темного Заліза та проклятими уламками кораблів уздовж узбережжя утримати болота можна лише за невсипущої пильності."}},faq={{q="Як дістатися до Багнокраю пішки?",a="Шукачі пригод з Альянсу зазвичай ідуть на північ із Лох Модану гірським перевалом Дун Алґаз. Мандрівники Орди, що йдуть із півночі, можуть перейти Міст Тандол з Аратійського нагір'я. Будьте обережні: за обидва проходи змагаються ворожі сили, як-от орки Драконячої Пащі й дворфи Темного Заліза.",al={"як дістатися до багнокраю","шлях до багнокраю","пішки до багнокраю"}},{q="Куди пливуть кораблі з Гавані Менетіл?",a="З причалів Гавані Менетіл ходять два головні пороми на Калімдор: один корабель пливе через Велике Море до Обердайна на березі Темного Узбережжя, а другий — на південь, до Острова Терамор у Багні Пилоброду.",al={"човни менетілу","кораблі гавані менетіл","куди пливе човен у багнокраї"}},{q="Що таке Ґрім Батол і чому його охороняють?",a="Ґрім Батол — прадавня дворфійська фортеця, покинута після Війни Трьох Молотів і згодом зайнята кланом Драконячої Пащі. Після Другої війни звільнена червона драконячий рід вигнала орків і запечатала гору. Могутні червоні драконороди й вірмороди патрулюють Брами Драконячої Пащі, щоб ніхто не увійшов до проклятих залів.",al={"чому дракони біля ґрім батола","червоні дракони ґрім батол","брами драконячої пащі"}},{q="Що сталося з Дун Модром?",a="Дун Модр — північна дворфійська твердиня, що стерегла Міст Тандол. Нещодавно на неї напали й захопили дворфи Темного Заліза на чолі з Балґарасом Мерзенним. Уцілілі під проводом Раґа Ґармасона тримають обложений табір неподалік і борються за повернення свого містечка.",al={"хто зруйнував дун модр","руїни дун модра","темне залізо в дун модрі"}},{q="Хто такий Ретіель Зеленовартовий?",a="Ретіель — прадавній болотяний звір, що живе на Зеленому Поясі Багнокраю. Він просить мандрівників допомогти стримати навалу агресивних гнолів-Мохошкірих і знищити хворих болотяних повзунів, щоб драговина могла відродитися.",al={"зелений пояс","ретіель багнокрай","хто такий зеленовартовий"}},{q="Звідки в болоті всі ці орки?",a="Орки належать до клану Драконячої Пащі, що під час Другої війни укріпився в Ґрім Батолі. Розгромлені звільненою червоною драконячою зграєю, уцілілі орки втекли вниз, у болота й пагорби, звідки досі нападають на дороги й мандрівників.",al={"чому орки в багнокраї","драконяча паща багнокрай","клан драконячої пащі багнокрай"}}},fp="8,418,24.524.0,23.601.0,22.527.0,18.503.0,40.301.0,41.216.0,41.343.0,26.268.0,31.214.0,46.277.0"}
P.entries["zone:winterspring"] = {n="Вінтерспрінг",s="Вінтерспрінг — величезна засніжена долина високо на північно-східних схилах Гори Гіджал, просто над зачарованими лісами Місячного Гаю й Сквернолісся. Цей край, відомий лютими морозами, давніми руїнами Високородних і мандрівними грізними хижаками, тримається довкола нейтральної гоблінської застави Евірлук. Це земля суворих природних небезпек: тут знаходять прихисток рештки синього драконячого роду, а на південних висотах доводиться протистояти демонічній скверні.",h="Вінтерспрінг — величезна засніжена долина високо на північно-східних схилах Гори Гіджал, просто над...",kw={"вінтерспрінг","евірлук","мазторіл","кел'теріл","синій драконячий рід","фурболги","нордрассіл"},ang={["class:Druid"]="Вінтерспрінг, що лежить високо над Місячним Гаєм, має для вас священне значення: саме тут під час Третьої війни Малфуріон Стормрейдж пробудив Друїдів Кігтя від їхнього прадавнього сну.",["faction:Alliance"]="Герої Альянсу часто навідуються до Ріверн Фроствінд на Камені Морозних Шаблезубів і невтомно трудяться на лютому морозі, щоб заслужити вірність славетних скакунів — Морозних Шаблезубів з Вінтерспрінга.",["profession:Herbalism"]="Вінтерспрінг — єдине відоме місце, де росте Крижана шапка, незамінна гірська трава, яку дуже цінують для складних алхімічних сумішей; тут також трапляються Гірський Срібношавлій і рідкісні квіти Чорного Лотосу.",["profession:Mining"]="Крижані скелі й стіни печер долини багаті на цінні мінерали: тут часто трапляються жили малого й багатого торію, а також рідкісні поклади справжнього срібла.",["race:NightElf"]="Вінтерспрінг тісно пов'язаний з історією вашого народу: тут курганні лігва, де тисячоліттями спочивали Друїди Кігтя, трагічні руїни Кел'Теріла й оголені корені Нордрассіла, пошкоджені в Битві за Гору Гіджал."},sec={{t="Край вічного морозу",b="Вінтерспрінг лежить на тисячі футів вище за довколишні нетрі, під свіжим гірським повітрям і невпинними хуртовинами. Величезні оголені корені Світового Дерева, Нордрассіла, прорізають замети, наче височенні дерев'яні арки, вигнуті й покручені у вирішальних битвах Третьої війни. Хоча більшу частину північного Калімдору вкривають густі ліси й там тепліше, Вінтерспрінг — тихий край негустих гірських лісів, скелястих урвищ і замерзлих озер, де живуть грізні морозні шаблезуби, химери, єті й зимові ведмеді з густим хутром."},{t="Перехрестя й застави",b="Щоб дістатися цього високого плато, треба пройти давніми висіченими переходами Твердині Деревопащих, які стережуть неосквернені фурболги, що пильно оглядають кожного мандрівника з боку Сквернолісся чи Місячного Гаю. У центрі долини стоїть Евірлук — квітуче торговельне містечко, яким керує картель Стімвідл. Гобліни радо вітають шукачів пригод і з Альянсу, і з Орди, широко відчиняючи каси: це незамінний прихисток, де є інженерія, торгівля й теплі вогнища проти пекучого гірського морозу."},{t="Давні привиди й сині дракони",b="За століття до появи нинішніх поселень давні ельфи звели на березі озера місто Кел'Теріл. Коли безрозсудні чародії з Високородних розбили проклятий Кристал Зін-Малора, ними заволоділо безумство, і досі неспокійні привиди блукають серед зруйнованих колон і замерзлих вод. Південніше здіймаються печерні висоти Мазторілу — споконвічна твердиня синього драконячого роду в Калімдорі. Тут виводок Чароткача Малігоса під наглядом захисниці-матрони Гале пильнує потоки таємної магії й дає відсіч місцевим загрозам."},{t="Тінь над ущелиною",b="Спокій Вінтерспрінга різко уривається на самій південній межі, біля Ущелини Темного Шепоту. Там елітні демонічні сили — рештки легіонів Третьої війни — повзають зубчастими каньйонами, перекриваючи високі підступи до вершини Гори Гіджал. Тим часом місцеві фурболги Зимопаду піддалися мерзенній скверні, і незалежні дослідники на кшталт Донови Сноуден вивчають цю заразу, доки вона не поглинула всіх звірів долини."}},faq={{q="Як дістатися до Вінтерспрінга?",a="Мандрівникам треба пройти Твердинею Деревопащих — мережею підземних тунелів на північному сході Сквернолісся. Щоб мирно пройти печерами, треба здобути довіру місцевих фурболгів Деревопащих, які нападають на всіх непроханих гостей, що здаються їм ворожими. За східним виходом одразу відкриваються засніжені схили Вінтерспрінга.",al={"дістатися до вінтерспрінга","як зайти у вінтерспрінг","вхід у вінтерспрінг","тунель деревопащих вінтерспрінг"}},{q="Хто керує містечком Евірлук?",a="Евірлуком керує картель Стімвідл, гоблінський торговий концерн. Завдяки суворій гоблінській жазі прибутку й нейтралітету мандрівники і з Орди, і з Альянсу можуть користуватися тутешніми розпорядниками польотів, ремонтниками, банківськими сховищами й товарами, якщо не порушують миру в межах містечка.",al={"хто керує евірлуком","фракція евірлука","чи евірлук нейтральний"}},{q="Що за привиди блукають Озером Кел'Теріл?",a="Це духи нічних ельфів-Високородних, що десять тисяч років тому жили в прадавньому місті Кел'Теріл. Коли їхні чаклуни взялися до викраденого Кристала Зін-Малора, той розколовся й вивільнив страшне прокляття. Експедиції високих ельфів, що прибули сюди століттями пізніше, так само збожеволіли й тепер приречені блукати замерзлими руїнами поруч зі своїми предками.",al={"привиди озера кел'теріл","духи руїн кел'теріл","хто біля кел'теріл"}},{q="Чому фурболги-Зимопади агресивні?",a="Фурболги-Зимопади піддалися неприродному спотворенню, що шириться краєм і довело їхній клан до шаленої ворожості. Тоді як сусідні Деревопащі міцно тримаються здорового глузду, Зимопади потрапили під темний вплив, тож дослідники на кшталт Донови Сноуден вивчають їхню скверну й очищують їхні табори.",al={"чому зимопади ворожі","скверна зимопадів","донова сноуден фурболги"}},{q="Хто живе в Мазторілі?",a="Мазторіл — головне гніздовище й прихисток синьої драконячого роду на Калімдорі. Глибоко в його печерних шпилях вірмороди, добірні дракончата й прадавні дракони стережуть могутні драконячі реліквії й таємні знання під пильним оком Гале, супутниці Аспекта Малігоса.",al={"дракони мазторіла","що таке мазторіл","сині дракони вінтерспрінгу"}},{q="Що таке Ущелина Темного Шепоту?",a="Ущелина Темного Шепоту — підступний каньйон на крайньому півдні долини, де засіли могутні добірні демони, що лишилися після Третьої війни. Це добре охоронюване прикордоння вздовж небезпечних стежок, що ведуть до висот Гори Гіджал.",al={"демони темного шепоту","що в ущелині темного шепоту","брама гіджал вінтерспрінг"}},{q="Чи можна тут навчитися їздити на морозних шаблезубах чи приручити їх?",a="На Камені Морозних Шаблезубів далеко на півночі долини нічний ельф Ріверн Фроствінд доглядає місцевих білих котів. Шукачі пригод, які допоможуть йому з припасами й захистом прайду, можуть довести, що гідні дізнатися таємниці вирощування морозного шаблезуба й їзди на ньому.",al={"морозний шаблезуб їздова","рівен морозний шаблезуб","як отримати морозного шаблезуба"}}},fp="12,467,26.561.0,23.475.0,26.540.0,31.471.0,29.342.0,30.316.0,45.381.0,43.326.0,28.272.0,26.260.0,39.291.0"}
P.entries["zone:zephras"] = {n="Острів Зефрас",s="Острів Зефрас — летючий острів, що ширяє в Небесній Тверді, Царстві Стихій повітря. Це прадавня домівка небороджених і місце, де починається їхній шлях. Нині їхнє суспільство постало перед загрозою зникнення: магія, що тримає острів, поступово вивітрюється. Зв'язок із сусідніми небесними краями обірвався, і мешканці острова борються з розпадом стихій і напливом біженців.",h="Острів Зефрас — летючий острів, що ширяє в Небесній Тверді, Царстві Стихій повітря.",kw={"острів зефрас","небесна твердь","небороджені","елементалі","валанаар","повітряні кораблі","біженці"},ang={["class:Shaman"]="Острів Зефрас, що лежить просто в Царстві Стихій повітря, показує, що стається зі стихійними землями, коли духи, які тримають їх у рівновазі, раптом зникають.",["race:Skyborne"]="Острів Зефрас — ваша прадавня домівка й місце, де починається ваш шлях, хоча його тиха краса приховує нагальну кризу: земля розсипається, а сила стихій згасає."},sec={{t="Край у піднебессі",b="Острів Зефрас — відокремлений клаптик суходолу, що дрейфує в безкраїх вітрах Небесної Тверді. Поколіннями небороджені жили тут пліч-о-пліч із місцевими повітряними елементалями, які допомагали підтримувати магічні течії, що тримали острів у повітрі. Та кілька століть тому ці стихійні охоронці зникли без сліду. Без їхньої присутності й опіки приховані чари, що тримають землю, поволі почали слабнути, і Зефрас помалу тріщить і втрачає рівновагу."},{t="Обірвані обрії",b="Зефрас був не єдиним притулком небороджених в Царстві Стихій. Небесною Твердю дрейфували й острови-побратими — Анвілас і Сіроккас, — але після зникнення елементалів зв'язок між ними урвався. Останнім часом біженці з цих сусідніх островів, що розсипаються, зуміли дістатися Зефраса в пошуках безпеки й принесли похмурі звістки: інші острови буквально розпадаються в них під ногами."},{t="Поріг до Азерота",b="Їхній власний острів поволі руйнується, тож небороджені Зефраса почали вдивлятися за межі Небесної Тверді — в бік Азерота. Із небесних доків Валанаара тепер вирушають повітряні кораблі, щоб прокласти рідкісні рятівні шляхи до світу смертних. Ці подорожі поєднують повітряні володіння просто з місцями в Азероті — зокрема з околицями Даларану в Горах Альтерак і Плато Небоглядів у Малгорі."}},faq={{q="Де розташований Острів Зефрас?",a="Острів Зефрас лежить не на поверхні Азерота, а в Небесній Тверді — Царстві Стихій повітря. Він ширяє серед вічних хмар і вітряних течій цих ефірних володінь.",al={"де острів зефрас","де знаходиться зефрас","у якому царстві зефрас"}},{q="Чому Острів Зефрас розвалюється?",a="Острів тримався завдяки місцевим повітряним елементалям, які колись жили пліч-о-пліч із небородженими. Кілька століть тому ці елементалі зникли, і магічні основи, що тримають і бережуть летючу землю, з часом почали поволі слабнути й руйнуватися.",al={"чому зефрас руйнується","руйнування острова зефрас","острів, що гине"}},{q="Що таке Анвілас і Сіроккас?",a="Це сусідні летючі острови в Небесній Тверді, де теж живуть небороджені. Коли елементалі зникли, Острів Зефрас утратив зв'язок з обома, а біженці, що звідти тікають, розповідають, що і Анвілас, і Сіроккас розсипаються в небуття.",al={"анвілас","сіроккас","інші острови небороджених"}},{q="Як дістатися з Острова Зефрас до Азерота й назад?",a="Небороджені тримають небесні доки в поселенні Валанаар. Звідти повітряні кораблі перетинають межу царств і приземляються в Азероті — біля Даларану в Горах Альтерак і на Плато Небоглядів у Малгорі.",al={"як покинути зефрас","повітряні кораблі зефраса","подорож до азерота"}},{q="Хто такі небороджені?",a="Небороджені — мешканці Острова Зефрас і його небесних островів-побратимів. Вони поколіннями жили в Небесній Тверді, а тепер бачать, як їхня летюча батьківщина поволі руйнується, бо магія, що тримає її вкупі, згасає.",al={"раса небороджених","хто живе на зефрасі"}},{q="Хто ще живе на Острові Зефрас, окрім небороджених?",a="Окрім мирних сіл і біженців, острів потерпає від місцевих розбійників, нічнокігтів, що живуть у печерах, і звірів, які населяють такі місця, як Лігво Верескунів і Печера Нічнокігтів.",al={"мешканці зефраса","вороги на зефрасі"}}},fp="12,364,13.457.0,16.440.0,20.405.0,30.189.0,34.257.0,30.248.0,54.216.0,21.226.0,47.194.0"}
